package ch.emed.converter.chmed16a.mapping;

import java.util.Map;

/** Localized fixed texts required by CH EMED (titles) and generated by the mapping. */
public final class Labels {

  /** Label keys. */
  public enum Key {
    TITLE_CARD,
    TITLE_PRESCRIPTION,
    SECTION_CARD,
    SECTION_PRESCRIPTION,
    SECTION_ORIGINAL,
    SECTION_ANNOTATION,
    NO_DOSAGE,
    NO_MEDICATION
  }

  private static final Map<String, Map<Key, String>> TEXTS =
      Map.of(
          "de",
          Map.of(
              Key.TITLE_CARD, "Medikationsplan",
              Key.TITLE_PRESCRIPTION, "Rezept",
              Key.SECTION_CARD, "Medikamentenliste",
              Key.SECTION_PRESCRIPTION, "Arzneimittelverordnung",
              Key.SECTION_ORIGINAL, "Original Darstellung",
              Key.SECTION_ANNOTATION, "Kommentar",
              Key.NO_DOSAGE, "Dosierung nicht angegeben",
              Key.NO_MEDICATION, "Keine Medikamente erfasst"),
          "fr",
          Map.of(
              Key.TITLE_CARD, "Plan de médication",
              Key.TITLE_PRESCRIPTION, "Ordonnance",
              Key.SECTION_CARD, "Liste des médicaments",
              Key.SECTION_PRESCRIPTION, "Prescription de médicaments",
              Key.SECTION_ORIGINAL, "Représentation originale",
              Key.SECTION_ANNOTATION, "Commentaire",
              Key.NO_DOSAGE, "Posologie non indiquée",
              Key.NO_MEDICATION, "Aucun médicament saisi"),
          "it",
          Map.of(
              Key.TITLE_CARD, "Piano farmacologico",
              Key.TITLE_PRESCRIPTION, "Prescrizione",
              Key.SECTION_CARD, "Lista dei medicamenti",
              Key.SECTION_PRESCRIPTION, "Prescrizione di medicamenti",
              Key.SECTION_ORIGINAL, "Rappresentazione originale",
              Key.SECTION_ANNOTATION, "Commento",
              Key.NO_DOSAGE, "Posologia non indicata",
              Key.NO_MEDICATION, "Nessun medicamento registrato"),
          "en",
          Map.of(
              Key.TITLE_CARD, "Medication Plan",
              Key.TITLE_PRESCRIPTION, "Prescription",
              Key.SECTION_CARD, "Medication list",
              Key.SECTION_PRESCRIPTION, "Medication prescription",
              Key.SECTION_ORIGINAL, "Original representation",
              Key.SECTION_ANNOTATION, "Comment",
              Key.NO_DOSAGE, "Dosage not specified",
              Key.NO_MEDICATION, "No medication recorded"));

  private Labels() {}

  /** Text for a CH EMED language such as {@code de-CH}. */
  static String get(String language, Key key) {
    return TEXTS.getOrDefault(language.substring(0, 2), TEXTS.get("de")).get(key);
  }

  /** The text of a key in every supported language (for recognising generated notes). */
  public static java.util.Set<String> all(Key key) {
    java.util.Set<String> texts = new java.util.LinkedHashSet<>();
    TEXTS.values().forEach(t -> texts.add(t.get(key)));
    return texts;
  }
}
